import React, { useEffect, useState } from "react";
import useApi from "../../../../hooks/useApi";
import { useNavigate, useParams } from "react-router-dom";
import { getLoggedInUser } from "../../../../helpers/authUtils";
import WholesalePriceDiscountsFormModal from "./WholesalePriceDiscountsFormModal";
import wholesalersApi from "../../../../api/wholesalers/wholesalersApi";
import WholesalePriceDscountsTable from "./WholesalePriceDiscountsTable";

const columns = [
  { name: "Banner", uid: "banner" },
  { name: "Title", uid: "title" },
  { name: "Percentage", uid: "percent" },
  { name: "Normal Price", uid: "normal_price" },
  { name: "Offer Price", uid: "offer_price" },
  { name: "Start Date", uid: "start" },
  { name: "End Date", uid: "end" },
  { name: "Active", uid: "is_active" },
  { name: "Actions", uid: "actions" },
];

function WholesalePriceDiscountsList() {
  const [openPriceDiscountFormModal, setopenPriceDiscountsFormModal] =
    useState(false);
  const navigate = useNavigate();
  const [priceDiscount, setPriceDiscount] = useState();
  const [priceDiscounts, setPriceDiscounts] = useState([]);
  const [data, setdata] = useState([]);
  const [updated, setUpdated] = useState(false);
  const [modalTitle, setmodalTitle] = useState("");
  const priceDiscountsActionsApi = useApi(
    wholesalersApi.wholesaleReceiptsAction
  );

  const [user, setUser] = useState();

  useEffect(() => {
    setUser(getLoggedInUser());
  }, []);

  const getPriceDiscounts = async (user) => {
    setPriceDiscounts([]);
    await priceDiscountsActionsApi.request({
      action: "WholesalerPriceDiscounts",
    });
  };

  useEffect(() => {
    getPriceDiscounts(user);
  }, [user]);

  useEffect(() => {
    getPriceDiscounts(user);
  }, [openPriceDiscountFormModal]);

  const handleEditAction = (item) => {
    setopenPriceDiscountsFormModal(true);

    // setUpdated(false)

    setPriceDiscount(item);
    setmodalTitle(`${item.title}`);
  };

  const handleAddAction = () => {
    setopenPriceDiscountsFormModal(true);

    setUpdated(false);

    setmodalTitle("Add new price discount");
    setPriceDiscount(null);
  };
  const handleDetailsAction = (item) => {
    navigate(`/payments/discounts/price/details/${item.id}`, {
      state: {
        item: item,
      },
    });
  };
  const handleDeleteAction = (item) => {
    navigate(`/payments/discounts/price/delete/${item.id}`);
  };

  useEffect(() => {
    if (priceDiscountsActionsApi.data && priceDiscountsActionsApi.data.length) {
      setPriceDiscounts(priceDiscountsActionsApi.data);
    }

    console.log("priceDiscountsActionsApi.data", priceDiscountsActionsApi.data);
  }, [priceDiscountsActionsApi.data]);

  useEffect(() => {}, [openPriceDiscountFormModal]);

  //Filtering data
  useEffect(() => {
    setdata(priceDiscounts);
  }, [priceDiscounts]);

  const handleFilter = (e) => {
    const search_param = e;

    if (
      priceDiscounts &&
      priceDiscounts.length > 0 &&
      search_param &&
      search_param !== ""
    ) {
      setdata(
        priceDiscounts.filter((x) =>
          x.title.toLowerCase().includes(search_param)
        )
      );
    } else {
      setdata(priceDiscounts);
    }
  };

  return (
    <div className="m-auto mt-14 md:mt-1">
      {openPriceDiscountFormModal && (
        <WholesalePriceDiscountsFormModal
          ismodalOpen={openPriceDiscountFormModal}
          setisModalOpen={setopenPriceDiscountsFormModal}
          priceDiscountToEdit={priceDiscount}
          updated={updated}
          setUpdated={setUpdated}
          modalTitle={modalTitle}
        />
      )}
      <WholesalePriceDscountsTable
        data={data}
        columns={columns}
        editAction={handleEditAction}
        detailsAction={handleDetailsAction}
        deleteAction={handleDeleteAction}
        addAction={handleAddAction}
        handleFilter={handleFilter}
      />
    </div>
  );
}

export default WholesalePriceDiscountsList;
